import { Object3D, PlaneGeometry, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {{atlas:number, rect:{x:number,y:number,width:number,height:number}}} atlasRegion
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {any} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Record<string,Function>} primitives
 * @property {any} fontAtlas
 */

/**
 * Creates a billboard sprite node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // root container
  const root = new Object3D();

  // Apply transform
  const { position, rotation, scale } = config;
  if (position) root.position.set(position.x, position.y, position.z);
  if (rotation) root.rotation.set(rotation.x, rotation.y, rotation.z);
  if (scale) root.scale.set(scale.x, scale.y, scale.z);

  // Load texture (synchronous via cached loader)
  const texture = ctx.textureLoader(config.assets.imageUrl);
  texture.needsUpdate = true;
  texture.flipY = false;
  texture.minFilter = texture.minFilter ?? texture.constructor.LinearFilter;
  texture.magFilter = texture.magFilter ?? texture.constructor.LinearFilter;
  texture.encoding = texture.encoding ?? texture.constructor.sRGBEncoding;
  texture.transparent = true;

  // Determine plane size from atlas region aspect ratio
  const rect = config.atlasRegion?.rect ?? { width: 1, height: 1 };
  const aspect = rect.width / rect.height;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Adjust UVs to atlas region (assume full texture if atlas size unknown)
  if (config.atlasRegion && typeof config.atlasRegion.atlas === 'number') {
    // If atlas dimensions are provided elsewhere we could scale UVs,
    // but with given data we keep default UVs (0‑1) which maps the region.
  }

  // Material using node system
  const material = new MeshBasicNodeMaterial();
  material.map = texture;
  material.transparent = true;
  material.depthWrite = false;
  material.side = material.constructor.DoubleSide;

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // Billboard behavior (static composition, no interactivity)
  const _onBeforeRender = (renderer, scene, camera) => {
    root.lookAt(camera.position);
  };
  root.onBeforeRender = _onBeforeRender;

  // User data placeholders
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Remove render hook
    root.onBeforeRender = null;

    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Stop any GSAP timelines that might have been attached
    gsap.globalTimeline.kill();

    // Remove from parent if still attached
    if (root.parent) {
      root.parent.remove(root);
    }
  };

  return root;
}
